findings.codeql_raw_query:
/**
 * @name Improper modification of object attributes
 * @description Using setattr with user-controlled attribute names can lead to unexpected behavior or code execution.
 * @kind path-problem
 * @problem.severity warning
 * @id py/improper-setattr
 * @tags security
 *       external/cwe/cwe-915
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module SetattrConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("setattr").getACall() and
      sink = call.getArg(1)
    )
  }
}

module SetattrFlow = TaintTracking::Global<SetattrConfig>;
import SetattrFlow::PathGraph

from SetattrFlow::PathNode source, SetattrFlow::PathNode sink
where SetattrFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Attribute name from $@ is used in setattr.", source.getNode(), "user input"
